import 'server-only';
import nodemailer from 'nodemailer';
import { env } from './env';

/**
 * Outgoing e-mail over SMTP: Mailpit locally (http://localhost:8025 shows every message),
 * the hosting provider's transactional mail in production (ADR-0009). Messages are plain
 * text first; links are the only dynamic content and are generated by the server.
 */
const transport = nodemailer.createTransport(env.SMTP_URL);

export type Mail = { to: string; subject: string; text: string };

export async function sendMail({ to, subject, text }: Mail): Promise<void> {
  await transport.sendMail({ from: env.MAIL_FROM, to, subject, text });
}

const SIGNATURE = '\n\n—\nКантора\nТози имейл е изпратен автоматично. Не отговаряйте на него.';

export const templates = {
  verifyEmail: (name: string, url: string): Omit<Mail, 'to'> => ({
    subject: 'Потвърдете имейла си — Кантора',
    text:
      `Здравейте, ${name},\n\n` +
      `За да завършите регистрацията, отворете връзката (валидна 24 часа):\n\n${url}\n\n` +
      'Ако не сте се регистрирали вие, просто игнорирайте този имейл.' +
      SIGNATURE,
  }),
  resetPassword: (name: string, url: string): Omit<Mail, 'to'> => ({
    subject: 'Смяна на парола — Кантора',
    text:
      `Здравейте, ${name},\n\n` +
      `Някой поиска смяна на паролата за този профил. Ако сте вие, отворете връзката (валидна 1 час):\n\n${url}\n\n` +
      'След смяната ще излезете от всички устройства. Двуфакторната защита остава включена.\n' +
      'Ако не сте поискали смяна, игнорирайте имейла: паролата ви не е променена.' +
      SIGNATURE,
  }),
  invitation: (officeName: string, roleLabel: string, url: string): Omit<Mail, 'to'> => ({
    subject: `Покана за ${officeName} — Кантора`,
    text:
      `Здравейте,\n\nПоканени сте в ${officeName} като ${roleLabel}.\n\n` +
      `За да приемете, отворете връзката (валидна 7 дни, за еднократна употреба):\n\n${url}\n\n` +
      'Ако не очаквате тази покана, игнорирайте имейла.' +
      SIGNATURE,
  }),
};
